class CookieSigner:
    """Signs and verifies unlock cookies scoped to a single artifact ID."""

    def __init__(self, secret_key: str) -> None:
        self._signer = TimestampSigner(secret_key, salt=_COOKIE_SALT)

    def make(self, artifact_id: str) -> str:
        """Produce a signed cookie value for the given artifact ID."""
        return self._signer.sign(artifact_id).decode("utf-8")

    def check(self, artifact_id: str, value: str, max_age_s: int) -> bool:
        """Verify a cookie value was signed for ``artifact_id`` and is fresh."""
        try:
            payload = self._signer.unsign(value, max_age=max_age_s)
        except Exception:
            return False
        return payload.decode("utf-8") == artifact_id

def unlock_artifact(
    artifact_id: str, request: Request, password: str = Form("")
) -> Response:
    """Password form target: on success set a signed, path-scoped cookie."""
    meta = _meta_of(request, artifact_id)
    if meta is None:
        return _not_found(artifact_id)
    if meta.password and not check_password(password, meta.password):
        return HTMLResponse(
            unlock_page(artifact_id, "Wrong password"), status_code=401
        )
    response = RedirectResponse(f"/a/{artifact_id}", status_code=303)
    response.set_cookie(
        key=f"art_{artifact_id}",
        value=request.app.state.signer.make(artifact_id),
        path=f"/a/{artifact_id}",
        httponly=True,
        secure=True,
        samesite="lax",
        max_age=settings.unlock_cookie_max_age_s,
    )
